// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns



// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Removing the Clone bound by using an in-place partition that does not materialize a pivot value will improve performance_score by avoiding per-partition cloning.
// MECHANISM-1: Fewer allocations/copies in partition reduces constant factors across recursive calls, especially for non-Copy T.
// EXPECT-1: performance_score > 0.9980
// RESULT-1: REFUTED (actual=0.997715730831976)
//
// HYPOTHESIS-2: Sorting the smaller partition first and looping on the larger (tail recursion elimination) will reduce recursion overhead and improve avg_time on large inputs.
// MECHANISM-2: Bounded stack depth and fewer function calls reduces overhead while preserving introsort worst-case guarantees.
// EXPECT-2: performance_score > 0.9980
// RESULT-2: REFUTED (actual=0.997715730831976)
pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    if len <= 32 { insertion_sort(arr); return; }

    // O(n) near-sorted check: count adjacent inversions
    let mut adj_inv = 0usize;
    for i in 0..len - 1 {
        if arr[i] > arr[i + 1] { adj_inv += 1; }
    }
    if adj_inv <= len / 8 {
        insertion_sort(arr);
        return;
    }

    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, max_depth);
}

fn introsort<T: Ord>(mut arr: &mut [T], mut depth: usize) {
    loop {
        let len = arr.len();
        if len <= 16 { insertion_sort(arr); return; }
        if depth == 0 { heap_sort(arr); return; }
        depth -= 1;

        let pi = partition_mo3(arr);
        let (left, right) = arr.split_at_mut(pi);

        // Recurse into smaller side; iterate on larger to reduce stack usage.
        if left.len() < right.len() - 1 {
            introsort(left, depth);
            arr = &mut right[1..];
        } else {
            introsort(&mut right[1..], depth);
            arr = left;
        }
    }
}

fn partition_mo3<T: Ord>(arr: &mut [T]) -> usize {
    let len = arr.len();
    let mid = len / 2;
    let last = len - 1;

    // Median-of-three pivot selection; place pivot at last-1
    if arr[0] > arr[mid] { arr.swap(0, mid); }
    if arr[0] > arr[last] { arr.swap(0, last); }
    if arr[mid] > arr[last] { arr.swap(mid, last); }
    arr.swap(mid, last - 1);

    // Partition using pivot at last-1 without cloning it.
    let pivot_idx = last - 1;
    let mut i = 1usize;
    let mut j = last - 2;

    loop {
        while i < pivot_idx && arr[i] < arr[pivot_idx] { i += 1; }
        while j > 0 && arr[j] > arr[pivot_idx] { j -= 1; }
        if i >= j { break; }
        arr.swap(i, j);
        i += 1;
        if j > 0 { j -= 1; }
    }
    arr.swap(i, pivot_idx);
    i
}

fn heap_sort<T: Ord>(arr: &mut [T]) {
    let len = arr.len();
    for i in (0..len / 2).rev() { sift_down(arr, i, len); }
    for i in (1..len).rev() {
        arr.swap(0, i);
        sift_down(arr, 0, i);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], mut root: usize, end: usize) {
    loop {
        let mut child = 2 * root + 1;
        if child >= end { break; }
        if child + 1 < end && arr[child] < arr[child + 1] { child += 1; }
        if arr[root] >= arr[child] { break; }
        arr.swap(root, child);
        root = child;
    }
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

